package controlador; import java.io.IOException; import jakarta.servlet.*; import jakarta.servlet.http.*; import modelo.ServicioDAO; public class EliminarServicio extends HttpServlet{protected void processRequest(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{new ServicioDAO().eliminar(Integer.parseInt(r.getParameter("id")));s.sendRedirect("listaServicios.jsp");} @Override protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{processRequest(r,s);}}
